using System;
using System.Drawing;
using System.IO;

namespace SimpleTextEditor.UI
{
    public static class Icons
    {
        private static Image LoadIcon(string base64)
        {
            byte[] bytes = Convert.FromBase64String(base64);
            var ms = new MemoryStream(bytes);
            return Image.FromStream(ms);
        }
        public static Image Headings => LoadIcon("");
        public static Image Lists => LoadIcon("");
        public static Image Bold => LoadIcon("");
